mapper.select:
SELECT a.*,
    e.name AS exam_name,
    es.subject_name AS subject_name,
    s.name AS student_name,
    c.name AS class_name
FROM answer_sheet a
LEFT JOIN exam e ON e.id = a.exam_id
LEFT JOIN exam_subject es ON es.id = a.exam_subject_id
LEFT JOIN student s ON s.id = a.student_id
LEFT JOIN class_info c ON c.id = s.class_id
WHERE a.deleted = 0

    AND a.exam_id = #{query.examId}


    AND a.exam_subject_id = #{query.examSubjectId}


    AND a.student_id = #{query.studentId}


    AND a.student_number = #{query.studentNumber}


    AND s.name LIKE CONCAT('%', #{query.studentName}, '%')


    AND s.class_id = #{query.classId}


    AND a.status = #{query.status}

ORDER BY a.create_time DESC

SELECT * FROM answer_sheet
WHERE student_id = #{studentId}
  AND exam_subject_id = #{examSubjectId}
  AND deleted = 0
LIMIT 1
